method add(lst: seq<int>) returns (result: int)
    requires |lst| > 0 // The list must be non-empty
    ensures forall i :: 0 <= i < |lst| ==> (i % 2 == 1 && lst[i] % 2 == 0 ==> result == SumEvenAtOddIndices(lst))
{
    result := 0;
    var n := |lst|;
    var i := 1; // Start from the first index (odd index)
    while i < n
        invariant 0 <= i <= n
        invariant result == SumEvenAtOddIndices(lst[..i])
    {
        if lst[i] % 2 == 0 {
            result := result + lst[i];
        }
        i := i + 2; // Move to the next odd index
    }
}

function SumEvenAtOddIndices(lst: seq<int>): int
    decreases |lst|
    requires |lst| > 0
{
    if |lst| == 1 {
        return 0; // No odd index to consider
    } else if |lst| == 2 {
        return if lst[1] % 2 == 0 then lst[1] else 0;
    } else {
        var sum := SumEvenAtOddIndices(lst[2..]);
        return if lst[1] % 2 == 0 then sum + lst[1] else sum;
    }
}
